-- Client-feedback batch 1. Back up the private database before running this complete file.
-- Equivalent to Django migration 0024_packaging_stock, including private-table RLS.
-- Existing orders and ingredient stock are not backfilled or deducted.
DO $packaging_0024$
BEGIN
    PERFORM set_config('lock_timeout', '10s', true);
    PERFORM set_config('search_path', 'django_app,pg_catalog', true);
    LOCK TABLE django_app.django_migrations IN EXCLUSIVE MODE;
    IF NOT EXISTS (SELECT 1 FROM django_app.django_migrations
        WHERE app='myapp' AND name='0023_raw_material_storage_guidance') THEN
        RAISE EXCEPTION 'Migration 0023 must be completed first.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM django_app.django_migrations
        WHERE app='myapp' AND name='0024_packaging_stock') THEN
        ALTER TABLE "myapp_orderitem" ALTER COLUMN "packaging_unit_cost" TYPE numeric(14, 6);
        CREATE TABLE "myapp_packagingitem" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(100) NOT NULL UNIQUE, "quantity" integer NOT NULL CHECK ("quantity" >= 0), "reorder_level" integer NOT NULL CHECK ("reorder_level" >= 0), "unit_cost" numeric(14, 6) NULL, "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
        CREATE TABLE "myapp_orderpackaging" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "packaging_name" varchar(100) NOT NULL, "quantity" integer NOT NULL CHECK ("quantity" >= 0), "unit_cost" numeric(14, 6) NULL, "allocated_at" timestamp with time zone NULL, "released_at" timestamp with time zone NULL, "order_item_id" bigint NOT NULL, "packaging_item_id" bigint NOT NULL);
        CREATE TABLE "myapp_packagingmovement" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "request_id" uuid NULL UNIQUE, "kind" varchar(10) NOT NULL, "change" integer NOT NULL, "balance_after" integer NOT NULL CHECK ("balance_after" >= 0), "reason" varchar(200) NOT NULL, "created_at" timestamp with time zone NOT NULL, "actor_id" integer NULL, "order_packaging_id" bigint NULL, "packaging_item_id" bigint NOT NULL);
        CREATE TABLE "myapp_productpackaging" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "quantity_per_item" integer NOT NULL CHECK ("quantity_per_item" >= 0), "packaging_item_id" bigint NOT NULL, "product_id" bigint NOT NULL);
        ALTER TABLE "myapp_orderpackaging" ADD CONSTRAINT "unique_order_packaging" UNIQUE ("order_item_id", "packaging_item_id");
        ALTER TABLE "myapp_orderpackaging" ADD CONSTRAINT "positive_order_packaging" CHECK ("quantity" >= 1);
        ALTER TABLE "myapp_packagingmovement" ADD CONSTRAINT "unique_packaging_order_movement" UNIQUE ("order_packaging_id", "kind");
        ALTER TABLE "myapp_productpackaging" ADD CONSTRAINT "unique_menu_packaging" UNIQUE ("product_id", "packaging_item_id");
        ALTER TABLE "myapp_productpackaging" ADD CONSTRAINT "positive_menu_packaging" CHECK ("quantity_per_item" >= 1);
        CREATE UNIQUE INDEX "packaging_name_ci_unique" ON "myapp_packagingitem" ((LOWER("name")));
        CREATE INDEX "myapp_packagingitem_name_eb6941b1_like" ON "myapp_packagingitem" ("name" varchar_pattern_ops);
        ALTER TABLE "myapp_orderpackaging" ADD CONSTRAINT "myapp_orderpackaging_order_item_id_90119bf3_fk_myapp_ord" FOREIGN KEY ("order_item_id") REFERENCES "myapp_orderitem" ("id") DEFERRABLE INITIALLY DEFERRED;
        ALTER TABLE "myapp_orderpackaging" ADD CONSTRAINT "myapp_orderpackaging_packaging_item_id_bab72998_fk_myapp_pac" FOREIGN KEY ("packaging_item_id") REFERENCES "myapp_packagingitem" ("id") DEFERRABLE INITIALLY DEFERRED;
        CREATE INDEX "myapp_orderpackaging_order_item_id_90119bf3" ON "myapp_orderpackaging" ("order_item_id");
        CREATE INDEX "myapp_orderpackaging_packaging_item_id_bab72998" ON "myapp_orderpackaging" ("packaging_item_id");
        ALTER TABLE "myapp_packagingmovement" ADD CONSTRAINT "myapp_packagingmovement_actor_id_ac90bb75_fk_auth_user_id" FOREIGN KEY ("actor_id") REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED;
        ALTER TABLE "myapp_packagingmovement" ADD CONSTRAINT "myapp_packagingmovem_order_packaging_id_8e5c5146_fk_myapp_ord" FOREIGN KEY ("order_packaging_id") REFERENCES "myapp_orderpackaging" ("id") DEFERRABLE INITIALLY DEFERRED;
        ALTER TABLE "myapp_packagingmovement" ADD CONSTRAINT "myapp_packagingmovem_packaging_item_id_e65be1d7_fk_myapp_pac" FOREIGN KEY ("packaging_item_id") REFERENCES "myapp_packagingitem" ("id") DEFERRABLE INITIALLY DEFERRED;
        CREATE INDEX "myapp_packagingmovement_actor_id_ac90bb75" ON "myapp_packagingmovement" ("actor_id");
        CREATE INDEX "myapp_packagingmovement_order_packaging_id_8e5c5146" ON "myapp_packagingmovement" ("order_packaging_id");
        CREATE INDEX "myapp_packagingmovement_packaging_item_id_e65be1d7" ON "myapp_packagingmovement" ("packaging_item_id");
        ALTER TABLE "myapp_productpackaging" ADD CONSTRAINT "myapp_productpackagi_packaging_item_id_1d9c91e3_fk_myapp_pac" FOREIGN KEY ("packaging_item_id") REFERENCES "myapp_packagingitem" ("id") DEFERRABLE INITIALLY DEFERRED;
        ALTER TABLE "myapp_productpackaging" ADD CONSTRAINT "myapp_productpackaging_product_id_7ab3d64e_fk_myapp_product_id" FOREIGN KEY ("product_id") REFERENCES "myapp_product" ("id") DEFERRABLE INITIALLY DEFERRED;
        CREATE INDEX "myapp_productpackaging_packaging_item_id_1d9c91e3" ON "myapp_productpackaging" ("packaging_item_id");
        CREATE INDEX "myapp_productpackaging_product_id_7ab3d64e" ON "myapp_productpackaging" ("product_id");
        ALTER TABLE "myapp_packagingitem" ENABLE ROW LEVEL SECURITY;
        ALTER TABLE "myapp_productpackaging" ENABLE ROW LEVEL SECURITY;
        ALTER TABLE "myapp_orderpackaging" ENABLE ROW LEVEL SECURITY;
        ALTER TABLE "myapp_packagingmovement" ENABLE ROW LEVEL SECURITY;
        INSERT INTO django_app.django_migrations (app,name,applied)
            VALUES ('myapp','0024_packaging_stock',CURRENT_TIMESTAMP);
    END IF;
    IF EXISTS (SELECT 1 FROM (VALUES ('myapp_packagingitem'),('myapp_productpackaging'),
        ('myapp_orderpackaging'),('myapp_packagingmovement')) AS required(name)
        WHERE NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            WHERE n.nspname='django_app' AND c.relname=required.name AND c.relkind='r' AND c.relrowsecurity)) THEN
        RAISE EXCEPTION 'Packaging tables or RLS do not match the recorded migration. Stop and review.';
    END IF;
    IF EXISTS (SELECT 1 FROM (VALUES ('unique_order_packaging'),('positive_order_packaging'),
        ('unique_packaging_order_movement'),('unique_menu_packaging'),('positive_menu_packaging')) AS required(name)
        WHERE NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace
            WHERE n.nspname='django_app' AND c.conname=required.name AND c.convalidated)) THEN
        RAISE EXCEPTION 'Packaging constraints do not match migration 0024. Stop and review.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
        JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='django_app'
            AND c.relname='packaging_name_ci_unique' AND i.indisunique AND i.indisvalid) THEN
        RAISE EXCEPTION 'Packaging name uniqueness index is missing. Stop and review.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='django_app'
        AND table_name='myapp_orderitem' AND column_name='packaging_unit_cost'
        AND numeric_precision=14 AND numeric_scale=6) THEN
        RAISE EXCEPTION 'Accepted packaging cost precision does not match migration 0024. Stop and review.';
    END IF;
END
$packaging_0024$;
SELECT app,name,applied FROM django_app.django_migrations
WHERE app='myapp' AND name='0024_packaging_stock';
